import glob,collections,re
try:
    import yaml
except ImportError:
    yaml=None
rows=[]
for f in sorted(glob.glob('*.yaml')):
    d=yaml.safe_load(open(f))
    rows.append((f[:-5],d))
c=collections.Counter()
opens=[]
for i,d in rows:
    if d.get('status')=='open':
        c[(d.get('kind'),str(d.get('owner')))]+=1
        opens.append((i,d.get('kind'),str(d.get('owner')),str(d.get('audience'))))
for k,v in sorted(c.items()): print(k,v)
print('OPEN TOTAL', len(opens))
print('non-protection', sum(1 for o in opens if o[1]!='protection'))
for o in opens: print(' ',o)
EOF

